import { expect, test, uniqueName } from "../../fixtures";

type VendorBody = { name: string; category: string; contact_email: string };

const examples = [
  { field: "name", value: "A" },
  { field: "category", value: "furniture" },
  { field: "contact_email", value: "not-an-email" },
] as const;

for (const { field, value } of examples) {
  test(`rejects invalid vendor field ${field}=${JSON.stringify(value)}`, { tag: "@VEN-02" }, async ({ apiAs }) => {
    // Arrange
    const member = await apiAs("member");
    const body: VendorBody = {
      name: uniqueName("Ven02 Acme"),
      category: "logistics",
      contact_email: "ops@acme.example",
    };
    (body as Record<string, string>)[field] = value;

    // Act
    const res = await member.post("/api/vendors", { data: body });
    const text = await res.text();

    // Assert
    expect(res.status(), text).toBe(422);
    const error = JSON.parse(text).error;
    expect(error.code, text).toBe("validation_error");
    const named: string[] = (error.fields ?? []).map((f: { field: string }) => f.field);
    expect(named, text).toContain(field);
  });
}
